const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

function buildTree(n) {
  const head = new Int32Array(n);
  head.fill(-1);
  const to = new Int32Array(2 * (n - 1));
  const next = new Int32Array(2 * (n - 1));
  let edgeIndex = 0;

  for (let i = 0; i < n - 1; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;

    to[edgeIndex] = b;
    next[edgeIndex] = head[a];
    head[a] = edgeIndex++;

    to[edgeIndex] = a;
    next[edgeIndex] = head[b];
    head[b] = edgeIndex++;
  }

  return { n, head, to, next };
}

function farthest(tree, start) {
  const { n, head, to, next } = tree;
  const dist = new Int32Array(n);
  dist.fill(-1);
  const parent = new Int32Array(n);
  const queue = new Int32Array(n);

  let begin = 0;
  let end = 0;
  queue[end++] = start;
  dist[start] = 0;
  parent[start] = -1;
  let last = start;

  while (begin < end) {
    const u = queue[begin++];
    last = u;

    for (let e = head[u]; e !== -1; e = next[e]) {
      const v = to[e];
      if (dist[v] === -1) {
        dist[v] = dist[u] + 1;
        parent[v] = u;
        queue[end++] = v;
      }
    }
  }

  return { vertex: last, parent };
}

function center(tree) {
  const endpoint = farthest(tree, 0).vertex;
  const result = farthest(tree, endpoint);
  let current = result.vertex;
  const path = [];

  while (current !== -1) {
    path.push(current);
    current = result.parent[current];
  }

  return path[Math.floor(path.length / 2)] + 1;
}

const n = nextInt();
const m = nextInt();
const circle = buildTree(n);
const square = buildTree(m);

console.log(`${center(circle)} ${center(square)}`);
